package com.sitionix.forgeai.api;
import com.sitionix.forgeai.domain.model.agentproxy.*; import com.sitionix.forgeai.domain.usecase.ManageAgentProjectAssets; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/infrastructure/agents/projects/{projectId}/assets")
public class ForgeAiProjectAssetsController { private final ManageAgentProjectAssets assets; public record Request(@NotBlank String name,@NotNull UUID sshConnectionId){} public record MonitoringRequest(@NotBlank String name,@NotNull AgentLogProviderType provider,@NotBlank String target,boolean enabled){}
 @GetMapping public List<AgentProjectAsset> list(@PathVariable UUID projectId){return assets.list(projectId);} @PostMapping public ResponseEntity<AgentProjectAsset> create(@PathVariable UUID projectId,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(assets.create(projectId,new CreateAgentProjectAssetCommand(r.name(),r.sshConnectionId())));} @GetMapping("/{assetId}") public AgentProjectAsset get(@PathVariable UUID projectId,@PathVariable UUID assetId){return assets.get(projectId,assetId);} @GetMapping("/{assetId}/metrics") public AgentAssetMetrics metrics(@PathVariable UUID projectId,@PathVariable UUID assetId){return assets.metrics(projectId,assetId);} @GetMapping("/{assetId}/capabilities") public AgentAssetCapabilities capabilities(@PathVariable UUID projectId,@PathVariable UUID assetId){return assets.capabilities(projectId,assetId);} @GetMapping("/{assetId}/monitoring") public List<AgentLogSource> monitoring(@PathVariable UUID projectId,@PathVariable UUID assetId){return assets.monitoring(projectId,assetId);} @PostMapping("/{assetId}/monitoring") public AgentLogSource monitor(@PathVariable UUID projectId,@PathVariable UUID assetId,@Valid @RequestBody MonitoringRequest r){return assets.monitor(projectId,assetId,new SaveAgentAssetMonitoringCommand(r.name(),r.provider(),r.target(),r.enabled()));} @DeleteMapping("/{assetId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID projectId,@PathVariable UUID assetId){assets.delete(projectId,assetId);} }
